const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type',
};

function tokenize(text) {
  const chars = [...text].filter(c => /[\u4e00-\u9fff]/.test(c) || /[a-zA-Z0-9]/.test(c));
  const ngrams = new Set();
  // 全部用 bigram+trigram（即使短查询），避免单字匹配长文本误报
  for (let n = 2; n <= 3; n++) {
    for (let i = 0; i <= chars.length - n; i++) {
      ngrams.add(chars.slice(i, i + n).join(''));
    }
  }
  // 若只剩 1 字（如"咳"），退化为单字
  if (ngrams.size === 0 && chars.length === 1) ngrams.add(chars[0]);
  return [...ngrams];
}

function score(text, terms) {
  // terms 是单字时（短查询），要求同时命中全部单字才算相关
  const allSingle = terms.every(t => t.length === 1);
  if (allSingle) {
    const all = terms.every(t => text.includes(t));
    if (!all) return 0;
    const len = text.length;
    const lenFactor = (len > 30 && len < 3000) ? 1.0 : 0.3;
    return 0.5 * lenFactor; // 单字命中给中低分
  }
  // 正常 bigram/trigram 查询
  let hits = 0;
  for (const t of terms) if (text.includes(t)) hits++;
  const coverage = terms.length ? hits / terms.length : 0;
  const len = text.length;
  const lenFactor = (len > 30 && len < 3000) ? 1.0 : 0.3;
  return coverage * lenFactor;
}



