// 体质判定并列时的参考顺序
const CONSTITUTION_ORDER = ['平和质', '气虚质', '阳虚质', '阴虚质', '痰湿质', '湿热质', '血瘀质', '气郁质', '特禀质'];

const DISCLAIMER_constitution = '本结果由中医体质规则模型自动生成，仅供健康参考，不构成医疗诊断。如有明显不适请及时就医。';

// ════════════════════════════════════════════════════════════
// 工具函数
// ════════════════════════════════════════════════════════════

/** 统计 text 中命中 keywords 的数量（子串匹配）
 *  @param {string} text     待匹配文本（症状描述）
 *  @param {string[]} keywords 关键词数组（体质特征 / 症状）
 *  @returns {number} 命中数 */
function matchKeywords(text, keywords) {
  if (!text || !Array.isArray(keywords) || keywords.length === 0) return 0;
  let hits = 0;
  for (const kw of keywords) {
    if (kw && text.includes(kw)) hits++;
  }
  return hits;
}

/** 命中明细版：返回 { hits, matched }（供内部评分使用） */
function matchKeywordsDetail(text, keywords) {
  const matched = [];
  if (text && Array.isArray(keywords)) {
    for (const kw of keywords) {
      if (kw && text.includes(kw)) matched.push(kw);
    }
  }
  return { hits: matched.length, matched };
}

/** 归一化证型/体质名：去空白、去括号内容、去「证/症/病」尾缀 */
function normalizeName(name) {
  if (!name) return '';
  return String(name)
    .replace(/[\s\u3000]+/g, '')            // 去空白
    .replace(/[（(].*?[)）]/g, '')            // 去括号内容
    .replace(/[证症病]$/, '')                // 去尾缀
    .toLowerCase();
}

/** 生成证型名匹配变体：原样 + 去尾缀 */
function nameVariants(raw) {
  const out = [raw];
  const t = String(raw).replace(/[证症]$/, '');
  if (t !== raw) out.push(t);
  return out;
}

/** 从对象中取第一个存在的字段值 */
function pick(obj, keys, fallback = null) {
  if (!obj || typeof obj !== 'object') return fallback;
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return fallback;
}

/** 统一转为字符串数组（兼容字符串/数组输入） */
function toArray(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v.map(s => (typeof s === 'string' ? s.trim() : s)).filter(Boolean);
  if (typeof v === 'string') return v.split(/[,，、;；\n]/).map(s => s.trim()).filter(Boolean);
  return [v];
}

/** 统一转为对象数组（兼容 [{...}] / [字符串] / 字符串） */
function toObjArray(v) {
  if (!v) return [];
  if (Array.isArray(v)) {
    return v.map(item => {
      if (typeof item === 'string') return { name: item };
      if (item && typeof item === 'object') return item;
      return { name: String(item) };
    });
  }
  if (typeof v === 'string') return v.split(/[,，、;；]/).map(s => ({ name: s.trim() })).filter(o => o.name);
  return [];
}

/** KV 读取并解析 JSON，失败返回 fallback */
async function kvGetJSON(env, key, fallback = null) {
  try {
    if (env && env.TCM_KV) {
      const v = await env.TCM_KV.get(key);
      if (v) return JSON.parse(v);
    }
  } catch (e) { /* KV 异常时静默降级到 fallback */ }
  return fallback;
}

/** 按前缀列出 KV 键值（返回 { 去掉前缀的name: 解析后的value }） */
async function kvListPrefix(env, prefix) {
  const out = {};
  try {
    if (env && env.TCM_KV) {
      const list = await env.TCM_KV.list({ prefix });
      for (const k of list.keys || []) {
        const name = k.name.replace(prefix, '');
        const v = await env.TCM_KV.get(k.name);
        if (v) {
          try { out[name] = JSON.parse(v); } catch (e) { out[name] = v; }
        }
      }
    }
  } catch (e) { /* KV 异常时返回空对象 */ }
  return out;
}

/** 提取体质对象中的特征关键词（兼容不同字段命名） */
function extractFeatures(info, fallback = []) {
  return toArray(pick(info, ['features', 'keywords', 'symptoms', 'key_symptoms', '特征', '症状', '特征表现']))
    || fallback;
}

/** 提取体质对象中的调理建议（兼容嵌套/平铺结构） */
function extractAdvice(info) {
  const adv = {};
  // 直接字段
  adv.diet = toObjArray(pick(info, ['diet', 'food', '饮食', '食疗', 'food_advice']));
  adv.lifestyle = toObjArray(pick(info, ['lifestyle', 'daily', '起居', '生活', 'lifestyle_advice']));
  adv.acupoints = toObjArray(pick(info, ['acupoints', '穴位', 'acupoint']));
  // 嵌套对象（advice / 调理建议 / 调理 / plan）
  const nested = pick(info, ['advice', '调理建议', '调理', 'plan'], null);
  if (nested && typeof nested === 'object') {
    if (!adv.diet.length) adv.diet = toObjArray(pick(nested, ['diet', 'food', '饮食', '食疗']));
    if (!adv.lifestyle.length) adv.lifestyle = toObjArray(pick(nested, ['lifestyle', 'daily', '起居', '生活']));
    if (!adv.acupoints.length) adv.acupoints = toObjArray(pick(nested, ['acupoints', '穴位']));
    // 字符串形式建议兜底
    if (!adv.diet.length && !adv.lifestyle.length && !adv.acupoints.length) {
      const str = pick(nested, ['summary', 'text', '内容'], '');
      if (str) adv.lifestyle = toObjArray(str);
    }
  }
  return adv;
}

/** 置信度计算：命中数/特征总数，命中≥3 时至少 0.75 */
function calcConfidence(hits, total) {
  if (total <= 0) return hits > 0 ? 0.5 : 0;
  let c = hits / total;
  if (hits >= 3) c = Math.max(c, 0.75);
  return Math.round(Math.min(1, c) * 100) / 100;
}

/** 从体质条目组装调理建议输出 */
function buildConstitutionAdvice(entry) {
  const info = entry.info || {};
  // 优先 KV 中自带建议，否则用内嵌建议
  let adv = extractAdvice(info);
  if (!adv.diet.length && !adv.lifestyle.length && !adv.acupoints.length) {
    const embedded = CONSTITUTIONS[entry.name];
    if (embedded && embedded.advice) {
      adv = {
        diet: toObjArray(embedded.advice.diet),
        lifestyle: toObjArray(embedded.advice.lifestyle),
        acupoints: toObjArray(embedded.advice.acupoints),
      };
    }
  }
  return adv;
}

/** 体质辨识 LLM 辅助：综合症状分析，返回 {constitution, confidence, analysis, advice} 或 null
 *  @param {string} symptoms 症状描述
 *  @param {object} env      Worker 环境
 *  @param {string} fallbackName 规则判定的体质（供 LLM 参考）
 *  @returns {Promise<object|null>} LLM 分析结果（失败返回 null，调用方回退规则）
 */
async function constitutionLLM(symptoms, env, fallbackName) {
  let cfg = null;
  try { cfg = await loadLlmConfig(env); } catch (e) { cfg = { ...DEFAULT_CONFIG_ai_diagnose }; }
  const provider = (cfg.provider || 'workers-ai').toLowerCase();
  if (provider !== 'external') return null; // 只支持 external LLM（DeepSeek）
  const base = (cfg.external_base || '').replace(/\/+$/, '');
  const key = cfg.external_key;
  const model = cfg.external_model;
  if (!base || !key || !model) return null;

  const prompt = [
    '你是一位精通中医体质辨识的资深中医师。请根据用户描述的症状，进行九种体质（平和质/气虚质/阳虚质/阴虚质/痰湿质/湿热质/血瘀质/气郁质/特禀质）辨识。',
    '要求：',
    '1. 仔细分析用户描述的每一个症状，判断其对应体质；',
    '2. 允许复合体质，但需给出最主要的体质；',
    '3. 语言通俗易懂，辨证依据要充分；',
    '4. 必须只输出一个 JSON 对象，不要输出任何其他文字。',
    'JSON 格式（严格遵循）：',
    '{',
    '  "constitution": "主要体质名称（九种之一）",',
    '  "confidence": 0.85,',
    '  "analysis": "详细的体质分析（至少150字）：①各症状对应的中医解释（为什么会这样）②为何判定为该体质③可能伴随的其他表现",',
    '  "advice": {',
    '    "diet": ["饮食建议1", "饮食建议2", "饮食建议3"],',
    '    "lifestyle": ["生活方式建议1", "建议2"],',
    '    "acupoints": ["穴位保健1（含按法）", "穴位保健2"]',
    '  }',
    '}',
  ].join('\n');
  const userMsg = '用户症状描述：\n' + symptoms + '\n\n（规则引擎初步判定为「' + (fallbackName || '未知') + '」体质，请结合分析综合判断）\n\n请输出 JSON 体质辨识结果。';

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), cfg.timeout_ms || 45000);
  try {
    const resp = await fetch(base + '/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + key },
      body: JSON.stringify({
        model,
        messages: [
          { role: 'system', content: prompt },
          { role: 'user', content: userMsg },
        ],
        max_tokens: (cfg.max_tokens || 1500),
        temperature: 0.4,
        stream: false,
      }),
      signal: controller.signal,
    });
    if (!resp.ok) throw new Error('LLM HTTP ' + resp.status);
    const data = await resp.json();
    const text = (data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '';
    if (!text) throw new Error('LLM 返回为空');
    const parsed = extractJson(text);
    if (parsed && parsed.constitution) return parsed;
    return null;
  } catch (e) {
    console.log('[constitution] LLM 体质辨识失败:', e.message);
    return null;
  } finally {
    clearTimeout(timer);
  }
}

// ════════════════════════════════════════════════════════════
// 1. 体质辨识
// ════════════════════════════════════════════════════════════

/** 体质辨识：症状 → 九种体质规则打分 → 判定 + 置信度 + 调理建议
 *  @param {string} symptoms 症状描述（如 "容易疲劳，气短，自汗"）
 *  @param {object} env      Worker 环境（含 TCM_KV 绑定；测试可传 null）
 *  @returns {Promise<object>} JSON 结果 */
async function analyzeConstitution(symptoms, env) {
  const text = String(symptoms || '').trim();
  if (!text) {
    return { error: '请输入症状描述', disclaimer: DISCLAIMER_constitution };
  }

  // 1) 加载体质库：KV 优先，内嵌回退
  let constitutionLib = null;
  let method = 'embedded';
  if (env && env.TCM_KV) {
    try {
      const listed = await kvListPrefix(env, 'tcm:constitution:');
      if (listed && Object.keys(listed).length > 0) {
        constitutionLib = listed;
        method = 'kv';
      }
    } catch (e) { /* 忽略，走内嵌 */ }
  }
  if (!constitutionLib) constitutionLib = Object.assign({}, CONSTITUTIONS);

  // 2) 规则打分：每个体质的特征关键词在症状文本中的命中数
  const scores = [];
  for (const [name, info] of Object.entries(constitutionLib)) {
    const features = extractFeatures(info);
    const detail = matchKeywordsDetail(text, features);
    if (detail.hits === 0) continue;
    scores.push({
      name,
      hits: detail.hits,
      confidence: calcConfidence(detail.hits, features.length),
      matched: detail.matched,
      info,
    });
  }

  // 排序：命中数优先，其次置信度，再按体质参考顺序
  scores.sort((a, b) => {
    if (b.hits !== a.hits) return b.hits - a.hits;
    if (b.confidence !== a.confidence) return b.confidence - a.confidence;
    const ia = CONSTITUTION_ORDER.indexOf(a.name);
    const ib = CONSTITUTION_ORDER.indexOf(b.name);
    return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
  });

  if (scores.length === 0) {
    // 规则未命中 → 仍尝试 LLM 判断（自由分析）
    const llm = await constitutionLLM(text, env, '');
    if (llm) {
      return {
        constitution: llm.constitution,
        confidence: typeof llm.confidence === 'number' ? llm.confidence : 0.5,
        analysis: llm.analysis || '',
        advice: {
          diet: toObjArray(llm.advice && llm.advice.diet),
          lifestyle: toObjArray(llm.advice && llm.advice.lifestyle),
          acupoints: toObjArray(llm.advice && llm.advice.acupoints),
        },
        matched: false,
        method: 'llm',
        disclaimer: DISCLAIMER_constitution,
      };
    }
    return {
      error: '未匹配到明确体质特征，请补充更多症状描述',
      matched: false,
      method,
      disclaimer: DISCLAIMER_constitution,
    };
  }

  const primary = scores[0];
  const info = primary.info || {};
  const description = pick(info, ['description', 'desc', '概述', '特征描述'], '')
    || (CONSTITUTIONS[primary.name] ? CONSTITUTIONS[primary.name].description : '');

  // LLM 综合辅助：规则结果 + LLM 分析结合
  let llmResult = null;
  try { llmResult = await constitutionLLM(text, env, primary.name); } catch (e) { /* 回退规则 */ }

  // 组装返回：LLM 成功时用 LLM 的体质/分析/建议，规则结果保留为 candidates 参考
  const finalName = (llmResult && llmResult.constitution) ? llmResult.constitution : primary.name;
  const finalConfidence = (llmResult && typeof llmResult.confidence === 'number')
    ? llmResult.confidence : primary.confidence;
  const finalAnalysis = (llmResult && llmResult.analysis) ? llmResult.analysis : '';
  const llmAdvice = (llmResult && llmResult.advice) || null;

  return {
    constitution: finalName,
    confidence: finalConfidence,
    matched_keywords: primary.matched,
    matched_count: primary.hits,
    description: description + (finalAnalysis ? '\n\n' + finalAnalysis : ''),
    analysis: finalAnalysis,
    advice: {
      diet: (llmAdvice && toObjArray(llmAdvice.diet)).length ? toObjArray(llmAdvice.diet) : buildConstitutionAdvice(primary).diet,
      lifestyle: (llmAdvice && toObjArray(llmAdvice.lifestyle)).length ? toObjArray(llmAdvice.lifestyle) : buildConstitutionAdvice(primary).lifestyle,
      acupoints: (llmAdvice && toObjArray(llmAdvice.acupoints)).length ? toObjArray(llmAdvice.acupoints) : buildConstitutionAdvice(primary).acupoints,
    },
    candidates: scores.slice(0, 3).map(s => ({
      name: s.name, hits: s.hits, confidence: s.confidence, matched: s.matched,
    })),
    method: llmResult ? 'llm+rule' : method,
    disclaimer: DISCLAIMER_constitution,
  };
}

// ════════════════════════════════════════════════════════════
// 2. 调理方案
// ════════════════════════════════════════════════════════════

/** 调理方案 AI 兜底：内置库未找到证型时，用 LLM 生成完整调理方案
 *  @param {string} patternName 用户输入的证型名
 *  @param {object} env         Worker 环境
 *  @returns {Promise<object|null>} 结构化方案（失败返回 null，调用方返回错误）
 */
async function planLLMFallback(patternName, env) {
  let cfg = null;
  try { cfg = await loadLlmConfig(env); } catch (e) { cfg = { ...DEFAULT_CONFIG_ai_diagnose }; }
  const provider = (cfg.provider || 'workers-ai').toLowerCase();
  if (provider !== 'external') return null; // 只支持 external LLM（DeepSeek）
  const base = String(cfg.external_base || '').replace(/\/+$/, '');
  const key = cfg.external_key;
  const model = cfg.external_model;
  if (!base || !key || !model) return null;

  const prompt = [
    '你是一位资深中医师。请为指定的中医证型生成一份完整的调理方案。',
    '要求：',
    '1. 证型分析要专业准确，说明病机（为什么会这样）、主要表现；',
    '2. 方剂推荐经典名方，注明组成或主治；',
    '3. 食疗建议具体可操作（食物+做法或吃法）；',
    '4. 穴位建议注明位置和按法；',
    '5. 生活方式建议实际可行；',
    '6. 必须只输出一个 JSON 对象，不要输出任何其他文字。',
    '7. **重要：JSON 的字段名必须严格使用英文**（pattern/formulas/diet/acupoints/lifestyle 等），不要使用中文字段名。',
    'JSON 格式（严格遵循，字段名英文）：',
    '{',
    '  "pattern": "证型名称",',
    '  "description": "证型分析（至少100字）：病机、主要表现、常见人群",',
    '  "principle": "治则治法（如 疏肝解郁，理气和中）",',
    '  "formulas": [{"name": "方剂名", "ingredients": "组成或说明", "method": "用法"}],',
    '  "diet": [{"name": "食疗名", "ingredients": "原料", "method": "做法", "efficacy": "功效"}],',
    '  "acupoints": [{"name": "穴位名", "location": "定位", "method": "按法", "duration": "时长"}],',
    '  "lifestyle": [{"category": "起居/情志/运动", "advice": "具体建议"}]',
    '}',
  ].join('\n');
  const userMsg = '请为证型「' + patternName + '」生成调理方案，输出 JSON。';

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), cfg.timeout_ms || 45000);
  try {
    const resp = await fetch(base + '/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + key },
      body: JSON.stringify({
        model,
        messages: [
          { role: 'system', content: prompt },
          { role: 'user', content: userMsg },
        ],
        max_tokens: Math.max(cfg.max_tokens || 0, 3000),
        temperature: 0.4,
        stream: false,
      }),
      signal: controller.signal,
    });
    if (!resp.ok) throw new Error('LLM HTTP ' + resp.status);
    const data = await resp.json();
    const text = (data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '';
    if (!text) throw new Error('LLM 返回为空');
    const parsed = extractJson(text);
    // [2026-08-26] 兼容 LLM 输出中文字段名（DeepSeek 有时用中文 key）
    if (parsed) {
      const cnMap = {
        '证型': 'pattern', '分析': 'description', '治则': 'principle',
        '方剂': 'formulas', '方药': 'formulas',
        '食疗': 'diet', '饮食': 'diet', '饮食调养': 'diet',
        '穴位': 'acupoints', '穴位保健': 'acupoints',
        '生活方式': 'lifestyle', '生活建议': 'lifestyle',
        '组成': 'ingredients', '用法': 'method', '功效': 'efficacy',
        '定位': 'location', '按法': 'method', '时长': 'duration',
        '建议': 'advice', '类别': 'category',
      };
      for (const [cn, en] of Object.entries(cnMap)) {
        if (parsed[cn] !== undefined && parsed[en] === undefined) {
          parsed[en] = parsed[cn];
        }
      }
      // 方剂对象兼容: {名方, 组成} → {name, ingredients}
      const normFormula = (f) => {
        if (!f || typeof f !== 'object') return f;
        const out = {};
        if (f.name) out.name = f.name;
        else if (f.名方) out.name = f.名方;
        if (f.ingredients) out.ingredients = f.ingredients;
        else if (f.组成) out.ingredients = f.组成;
        if (f.method) out.method = f.method;
        else if (f.用法) out.method = f.用法;
        return out;
      };
      if (Array.isArray(parsed.formulas)) parsed.formulas = parsed.formulas.map(normFormula);
      else if (parsed.formulas && typeof parsed.formulas === 'object') {
        parsed.formulas = [normFormula(parsed.formulas)];
      }
    }
    if (parsed && (parsed.pattern || parsed.证型)) return parsed;
    return null;
  } catch (e) {
    console.log('[plan] LLM 调理方案兜底失败:', e.message);
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/** 调理方案：证型名 → KV tcm:pattern:* → 结构化方案
 *  @param {string} patternName 证型名（如 "肝气郁结" / "ganyu"）
 *  @param {object} env         Worker 环境（含 TCM_KV 绑定；测试可传 null）
 *  @returns {Promise<object>} JSON 结果 */
async function getPlan(patternName, env) {
  const raw = String(patternName || '').trim();
  if (!raw) {
    return { error: '请输入证型名', disclaimer: DISCLAIMER_constitution };
  }

  const variants = nameVariants(raw);
  let data = null;
  let method = 'embedded';

  // 1) KV 查询（优先）
  if (env && env.TCM_KV) {
    try {
      // 1a) 直接 get 尝试（key 可能是证型名或 id）
      for (const cand of variants) {
        const v = await kvGetJSON(env, `tcm:pattern:${cand}`);
        if (v) { data = v; method = 'kv'; break; }
      }
      // 1b) 前缀遍历匹配（容忍 key 命名差异，如 tcm:pattern:肝气郁结 / ganyu）
      if (!data) {
        const listed = await kvListPrefix(env, 'tcm:pattern:');
        const normVariants = variants.map(normalizeName).filter(Boolean);
        for (const [key, val] of Object.entries(listed)) {
          const normKey = normalizeName(key);
          // [2026-08-26] 精确度修复: 模糊匹配要求 key 与查询长度差 ≤1,
          // 避免"气阴两虚"误匹配"气虚"(长度差2)。完全包含且差异小的才算命中。
          const keyMatches = normVariants.some(v =>
            normKey === v ||                        // 完全相等
            (v.length >= 3 && normKey.includes(v) && normKey.length - v.length <= 1) ||  // key 更长且接近
            (normKey.length >= 3 && v.includes(normKey) && v.length - normKey.length <= 1)  // 查询更长且接近
          );
          if (keyMatches) {
            data = val; method = 'kv'; break;
          }
        }
      }
    } catch (e) { /* 忽略，走内嵌 */ }
  }

  // 2) 内嵌证型库回退
  if (!data) {
    const normVariants = variants.map(normalizeName).filter(Boolean);
    for (const pid of Object.keys(PATTERNS)) {
      const p = PATTERNS[pid];
      const candNames = [pid, p.name || ''].map(normalizeName).filter(Boolean);
      if (normVariants.some(v => candNames.includes(v) || candNames.some(c => c.includes(v)))) {
        data = p; method = 'embedded'; break;
      }
    }
  }

  // [2026-08-26] 修复模糊误匹配: KV/内嵌匹配到的 data 若无核心内容(方剂/饮食/穴位),
  // 说明是模糊匹配(如"气阴两虚"误匹配"气虚"), 视为未命中 → 走 AI 兜底
  // 注意: KV 数据结构是中文键(推荐方剂/饮食建议/穴位按摩), 必须兼容
  const dataHasContent = (d) => {
    if (!d) return false;
    const f = d.formulas || d.formula || d['推荐方剂'] || d['方剂'] || (d.advice && d.advice.formulas);
    const diet = d.diet || d.diet_therapy || d['饮食建议'] || d['饮食'] || d['食疗'] || (d.advice && d.advice.diet);
    const acup = d.acupoints || d.acupressure || d['穴位按摩'] || d['穴位'] || (d.advice && d.advice.acupoints);
    const hasAny = (x) => Array.isArray(x) ? x.length > 0 : (typeof x === 'object' && x !== null ? Object.keys(x).length > 0 : !!x);
    return hasAny(f) || hasAny(diet) || hasAny(acup);
  };

  if (!data || !dataHasContent(data)) {
    // AI 兜底：内置库未找到(或模糊误匹配无内容) → 用 LLM 生成完整调理方案
    const llmPlan = await planLLMFallback(raw, env);
    if (llmPlan) {
      return {
        pattern: llmPlan.pattern || raw,
        pattern_id: '',
        category: '',
        found: true,
        description: llmPlan.description || '',
        symptoms: toArray(llmPlan.symptoms),
        tongue: llmPlan.tongue || '',
        pulse: llmPlan.pulse || '',
        principle: llmPlan.principle || '',
        formulas: toObjArray(llmPlan.formulas || llmPlan.formula),
        diet: toObjArray(llmPlan.diet || llmPlan.diet_therapy),
        acupoints: toObjArray(llmPlan.acupoints || llmPlan.acupressure),
        lifestyle: toObjArray(llmPlan.lifestyle || llmPlan.lifestyle_advice),
        method: 'llm',
        ai_generated: true,
        disclaimer: DISCLAIMER_constitution,
      };
    }
    return {
      error: `未找到证型「${raw}」`,
      found: false,
      hint: '请尝试：肝气郁结 / 脾气虚弱 / 阴虚火旺 / 湿热内蕴 / 寒湿困脾 / 肾阳虚衰 等',
      method,
      disclaimer: DISCLAIMER_constitution,
    };
  }

  // 3) 组装结构化结果（兼容不同字段命名）
  return {
    pattern: pick(data, ['name', 'pattern', '证型'], ''),
    pattern_id: pick(data, ['id', 'pattern_id', 'key'], ''),
    category: pick(data, ['category', '分类'], ''),
    found: true,
    description: pick(data, ['description', 'desc', '概述', '描述'], ''),
    symptoms: toArray(pick(data, ['symptoms', 'key_symptoms', '症状'], [])),
    tongue: pick(data, ['tongue', '舌象'], ''),
    pulse: pick(data, ['pulse', '脉象'], ''),
    principle: pick(data, ['principle', '治法', '治则', '调理原则'], ''),
    formulas: toObjArray(pick(data, ['formulas', 'formula', '推荐方剂', '方剂'], [])),
    diet: toObjArray(pick(data, ['diet', 'diet_therapy', '饮食建议', '食疗', '饮食'], [])),
    acupoints: toObjArray(pick(data, ['acupoints', '穴位按摩', '穴位'], [])),
    lifestyle: toObjArray(pick(data, ['lifestyle', 'lifestyle_advice', '生活调理', '生活建议', '起居'], [])),
    method,
    disclaimer: DISCLAIMER_constitution,
  };
}

